package akogen.fabric.v6;
import java.io.*;import java.net.*;import java.util.*;import javax.net.ssl.*;
/** Minimal bounded MQTT 3.1.1 over authenticated TLS; no chat, model bytes or account tokens. */
public final class MqttLink implements Closeable {
 public interface Listener {void message(String topic,byte[] body);}
 final String host;final int port;final Listener listener;SSLSocket socket;DataInputStream input;DataOutputStream output;int sequence=1;Set<String> subscriptions=new HashSet<String>();
 public MqttLink(String host,int port,Listener listener){this.host=host;this.port=port;this.listener=listener;}
 static void string(DataOutputStream out,String value)throws IOException{byte[] bytes=value.getBytes("UTF-8");if(bytes.length>512)throw new IOException("MQTT string too long");out.writeShort(bytes.length);out.write(bytes);}
 public void open()throws Exception{socket=(SSLSocket)SSLSocketFactory.getDefault().createSocket();socket.connect(new InetSocketAddress(host,port),5000);socket.setSoTimeout(5000);SSLParameters settings=socket.getSSLParameters();settings.setEndpointIdentificationAlgorithm("HTTPS");socket.setSSLParameters(settings);socket.startHandshake();input=new DataInputStream(socket.getInputStream());output=new DataOutputStream(socket.getOutputStream());ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream body=new DataOutputStream(bytes);string(body,"MQTT");body.writeByte(4);body.writeByte(2);body.writeShort(30);string(body,"akg-"+UUID.randomUUID().toString().replace("-","").substring(0,19));send(0x10,bytes.toByteArray());Frame reply=read(false);if(reply==null||reply.type!=2||reply.body.length!=2||reply.body[1]!=0)throw new IOException("Relay rejected MQTT connection");socket.setSoTimeout(300);}
 static final class Frame {int type,flags;byte[] body;Frame(int first,byte[] body){type=first>>4;flags=first&15;this.body=body;}}
 Frame read(boolean timeoutOkay)throws IOException{int first;try{first=input.readUnsignedByte();}catch(SocketTimeoutException e){if(timeoutOkay)return null;throw e;}int length=0,multiplier=1,digit=0;for(int n=0;n<4;n++){digit=input.readUnsignedByte();length+=(digit&127)*multiplier;if(length>4096)throw new IOException("Relay frame exceeds limit");if((digit&128)==0)break;if(n==3)throw new IOException("Malformed MQTT length");multiplier*=128;}byte[] body=new byte[length];input.readFully(body);return new Frame(first,body);}
 synchronized void send(int type,byte[] body)throws IOException{if(body.length>4096)throw new IOException("Relay frame exceeds limit");output.writeByte(type);int left=body.length;do{int digit=left%128;left/=128;if(left>0)digit|=128;output.writeByte(digit);}while(left>0);output.write(body);output.flush();}
 int next(){sequence=(sequence+1)&65535;return sequence==0?++sequence:sequence;}
 public void subscriptions(Set<String> desired)throws IOException{if(subscriptions.equals(desired))return;Set<String> add=new LinkedHashSet<String>(desired),remove=new LinkedHashSet<String>(subscriptions);add.removeAll(subscriptions);remove.removeAll(desired);if(!remove.isEmpty()){ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeShort(next());for(String topic:remove)string(out,topic);send(0xa2,b.toByteArray());}if(!add.isEmpty()){ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeShort(next());for(String topic:add){string(out,topic);out.writeByte(0);}send(0x82,b.toByteArray());}subscriptions=new HashSet<String>(desired);}
 public void publish(String topic,byte[] value)throws IOException{if(value.length>2048)throw new IOException("Cosmetic snapshot too large");ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);string(out,topic);out.write(value);send(0x30,bytes.toByteArray());}
 public void poll()throws IOException{Frame f=read(true);if(f==null)return;if(f.type==3){DataInputStream in=new DataInputStream(new ByteArrayInputStream(f.body));String topic=in.readUTF();if(topic.length()>160)throw new IOException("Invalid relay topic");int qos=(f.flags>>1)&3;if(qos>1)throw new IOException("Unsupported relay QoS");int ack=qos==1?in.readUnsignedShort():0;byte[] body=new byte[in.available()];in.readFully(body);if(body.length<=2048)listener.message(topic,body);if(qos==1)send(0x40,new byte[]{(byte)(ack>>8),(byte)ack});}else if(f.type==9){for(int n=2;n<f.body.length;n++)if((f.body[n]&255)==128)throw new IOException("Relay subscription refused");}else if(f.type==14)throw new IOException("Relay disconnected");}
 public void ping()throws IOException{send(0xc0,new byte[0]);}
 public void close(){try{if(socket!=null)socket.close();}catch(IOException ignored){}socket=null;}
}
